after:
const selected={ownerEmail:document.getElementById('pe_owner').value,deputyEmail:document.getElementById('pe_deputy').value};
const displayedOwner = record.pendingAssignment?.ownerEmail || record.assignment.ownerEmail;
if((currentRole==='admin' && record.revision===0 && !record.source) || selected.ownerEmail!==displayedOwner || (currentRole==='admin' && selected.deputyEmail!==record.assignment.deputyEmail))assignment=currentRole==='admin'?selected:{ownerEmail:selected.ownerEmail};

if (!result || !isProjectEditorSessionCurrent(session)) return;
if(result.transferred){
  projectMutationInFlight = false;
  draftEditorRecord = undefined;
  closeModal('projEditOverlay',{force:true});
  showSaveToast(`Published. Project Manager transferred to ${result.ownerName || result.ownerEmail}. You no longer have owner-based editing access.`);
  draftController.reset(); draftsLoadedKey=''; syncDraftWorkspace();
  return;
}
